    private static LocalizedResourceEntry E(string key, string english, string simplifiedChinese, string traditionalChinese) =>
        new(
            key,
            [
                english,
                simplifiedChinese,
                traditionalChinese,
                Translations.Get(key, 0),
                Translations.Get(key, 1),
                Translations.Get(key, 2),
                Translations.Get(key, 3),
                Translations.Get(key, 4),
                Translations.Get(key, 5),
                Translations.Get(key, 6),
                Translations.Get(key, 7),
                Translations.Get(key, 8),
                Translations.Get(key, 9),
                Translations.Get(key, 10),
                Translations.Get(key, 11)
            ]);

    private static class Translations
    {
        private static readonly IReadOnlyDictionary<string, string[]> Rows =
            Parse(Table1, Table2, Table3, Table4, Table5, Table6, Table7, Table8, Table9, Table10, Table11, Table12, Table13, Table14, Table15, Table16);

        internal static string Get(string key, int languageIndex) =>
            Rows.TryGetValue(key, out var values) && languageIndex < values.Length
                ? values[languageIndex]
                : throw new InvalidOperationException(
                    $"Missing conversion translation for '{key}' at language index {languageIndex}.");

        private static IReadOnlyDictionary<string, string[]> Parse(params string[] tables)
        {
            var result = new Dictionary<string, string[]>(StringComparer.Ordinal);
            foreach (var table in tables)
            {
                foreach (var line in table.Split('\n', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries))
                {
                    var columns = line.Split('|');
                    if (columns.Length != 13)
                    {
                        throw new InvalidOperationException($"Conversion translation row '{columns[0]}' has {columns.Length - 1} values; expected 12.");
                    }

                    if (!result.TryAdd(columns[0], columns[1..]))
                    {
                        throw new InvalidOperationException($"Duplicate conversion translation row: {columns[0]}");
                    }
                }
            }

            return result;
        }

